        top: 100,
        behavior: 'smooth'
      })
      setTimeout(() => scrollToTargetByKey(2), 300)
    })
  }, 1200)
})

const scrollHandler = (key: string | number) => {
  current.value = key as number
}

const { scrollToTargetByKey, setDistance } = useScrollElementAnchors(container, scrollHandler, rem2px(7.24))

